head.script:

	scwin.onpageload = function() {
        window.date;
		window.min; 
		window.sec; 
		window.milisec; 
		window.before; 
		window.after;
	};

	scwin.onpageunload = function() {

	};

    scwin.trigger1_onclick = function() {
        var jsonData = [
            {col1:"111111",col2:"222222",col3:"333333",col4:"444444",col5:"444444",col6:"444444",col7:"444444"}
        ];
        for(var i=0; i<4000; i++){
            jsonData.push({col1:"111111",col2:"222222",col3:"333333",col4:"444444",col5:"444444",col6:"444444",col7:"444444"})

        }
        dataList1.setJSON(jsonData);
    }
        scwin.checkBeforeTime = function(){
            date = new Date();
            min = date.getMinutes();
            sec = date.getSeconds();
            milisec = date.getMilliseconds();
            before = (min*60 + sec)*1000 + milisec;
			console.log("before : " + before);
        }

        scwin.checkAfterTime = function(){
            date = new Date();
            min = date.getMinutes();
            sec = date.getSeconds();
            milisec = date.getMilliseconds();
            after = (min*60 + sec)*1000 + milisec;
			console.log("after : " + after);			
        }

        scwin.compareTime = function(){
			console.log("-------------");				
			console.log("Math.abs(after - before) : " + Math.abs(after - before));		
            return Math.abs(after - before) <= 2300;
        }

		scwin.unitTest = function() {
            //init
            WebSquare.wUnit.start();
            WebSquare.wUnit.addCommand("pause", "1500");

            WebSquare.wUnit.addCommand("set", "scwin.checkBeforeTime()");
            WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
            WebSquare.wUnit.addCommand("set", "scwin.checkAfterTime()");
            WebSquare.wUnit.addCommand("pause", "500");

		    WebSquare.wUnit.addCommand("assert", "scwin.compareTime()","true");
            WebSquare.wUnit.addCommand("pause", "500");

            //Run  and stop
            WebSquare.wUnit.run();
            WebSquare.wUnit.stop();
        }
		scwin.unitTest()
